func _run_tests() -> void:
	var path := "res://story/consequence_story.json"
	if not check("file_exists", FileAccess.file_exists(path), "Il file res://story/consequence_story.json deve esistere"):
		return

	var file := FileAccess.open(path, FileAccess.READ)
	if not check("file_open", file != null, "Impossibile aprire consequence_story.json"):
		return

	var json := JSON.new()
	var err := json.parse(file.get_as_text())
	if not check("json_valid", err == OK, "consequence_story.json deve contenere JSON valido: %s" % json.get_error_message()):
		return

	var data: Variant = json.data
	if not check("has_lines", data is Dictionary and data.has("lines"), "consequence_story.json deve contenere la chiave 'lines'"):
		return

	var raw_lines: Array = data["lines"]
	var lines: Array[Dictionary] = []
