		if item is Dictionary:
			lines.append(item)

	var main := await instantiate_scene("res://story/story_screen.tscn")
	if not check("scene_loaded", main != null, "La scena story_screen.tscn deve caricarsi correttamente"):
		return

	var interpreter := find_by_name(main, "StoryInterpreter") as StoryInterpreter
	var choice_menu := find_by_name(main, "ChoiceMenu") as ChoiceMenu
	if not check("nodes_exist", interpreter != null and choice_menu != null, "StoryInterpreter e ChoiceMenu devono essere presenti"):
		return

	var container := choice_menu.get_node_or_null("VBoxContainer") as VBoxContainer
	if not check("container_exists", container != null, "ChoiceMenu deve contenere un VBoxContainer"):
		return

	var recorder := LineRecorder.new()
	main.add_child(recorder)
	interpreter.dialogue_box = recorder

	# Percorso 1: Scelta 'Prendi la mappa' (indice 0)
	interpreter.clear_variables()
	recorder.texts.clear()
	interpreter.run_story(lines)
	await wait_frames(3)

	if not check("buttons_shown_1", container.get_child_count() >= 2, "Il menu di scelta deve mostrare 2 pulsanti"):
		return

	var btn_yes := container.get_child(0) as BaseButton
	await click_button(btn_yes)
	await wait_frames(5)

	var has_map_val = interpreter.get_variable("has_map")
	check("map_true", has_map_val == true, "Scegliendo di prendere la mappa, has_map deve essere true")

	var line_map_found := false
	var line_nomap_found := false
	var line_end_found := false
	for t in recorder.texts:
		if t.contains("Consultando la mappa"):
			line_map_found = true
		if t.contains("Senza mappa"):
			line_nomap_found = true
		if t.contains("Siamo arrivati alla fine del corridoio"):
			line_end_found = true

	check("line_with_map", line_map_found, "Nel percorso con la mappa deve apparire la battuta sul passaggio segreto")
	check("no_line_without_map", not line_nomap_found, "Nel percorso con la mappa NON deve apparire la battuta sul buio")
	check("end_reached_1", line_end_found, "Il percorso 1 deve raggiungere la battuta finale di Marco")

	# Percorso 2: Scelta 'Lascia la mappa' (indice 1)
	interpreter.clear_variables()
	recorder.texts.clear()
	interpreter.run_story(lines)
	await wait_frames(3)

	if not check("buttons_shown_2", container.get_child_count() >= 2, "Il menu di scelta deve mostrare 2 pulsanti anche al secondo avvio"):
		return

	var btn_no := container.get_child(1) as BaseButton
	await click_button(btn_no)
	await wait_frames(5)

	has_map_val = interpreter.get_variable("has_map")
	check("map_false", has_map_val == false, "Scegliendo di non prendere la mappa, has_map deve essere false")

	line_map_found = false
	line_nomap_found = false
	line_end_found = false
	for t in recorder.texts:
		if t.contains("Consultando la mappa"):
			line_map_found = true
		if t.contains("Senza mappa"):
			line_nomap_found = true
		if t.contains("Siamo arrivati alla fine del corridoio"):
			line_end_found = true

	check("line_without_map", line_nomap_found, "Nel percorso senza mappa deve apparire la battuta sul buio")
	check("no_line_with_map", not line_map_found, "Nel percorso senza mappa NON deve apparire la battuta sulla mappa")
	check("end_reached_2", line_end_found, "Il percorso 2 deve raggiungere la battuta finale di Marco")

